/**
 * The Adhan catalogue.
 *
 * Two distinct sets, never merged in the UI:
 *
 *  1. **The supplied recordings** — generated by `scripts/process-audio.mjs`.
 *     Their licence is unknown and no written authorisation exists, so
 *     `bundled` is `false`: the files live in `audio-cleaned/` (outside
 *     `public/` and outside `res/raw/`), and `scripts/check-release-assets.mjs`
 *     fails a production build if one of them reappears in a shipped folder.
 *     The metadata stays so the owner can document what was recorded and switch
 *     `bundled` back on the day a permission is obtained.
 *  2. **The verified CC0 recording** — « Beautiful adhan » by Adam-synagda,
 *     published on Wikimedia Commons under CC0 1.0. Its provenance, measured
 *     duration, hashes and licence are recorded in `src/core/data/adhan-cc0.json`.
 *     It is shipped and is the default sound for a new installation.
 *
 * The app also keeps three synthesised test chimes and the user's own imports,
 * which are stored in IndexedDB and never leave the device.
 */

import catalogJson from '../core/data/audio-catalog.json';
import cc0Json from '../core/data/adhan-cc0.json';

export interface AdhanTrack {
  number: number;
  id: string;
  name: string;
  /** Path the PWA would serve *if* redistribution were authorised. */
  publicPath: string;
  /** Android raw resource name the APK would use *if* authorised. */
  androidRaw: string;
  /** Original file name, e.g. `azan1.mp3`. */
  sourceName: string;
  /** Cleaned copy kept outside the shipped folders. */
  localCopy: string;
  /** False while redistribution is not authorised. */
  bundled: boolean;
  durationSec: number;
  bytes: number;
  sampleRate: number;
  channels: number;
  bitrateKbps: number;
  sha256: string;
}

/** A recording whose licence explicitly allows redistribution. */
export interface BundledAdhanTrack {
  id: string;
  name: string;
  title: string;
  author: string;
  authorPage: string;
  sourcePage: string;
  sourceProject: string;
  license: string;
  licenseName: string;
  licenseUrl: string;
  attribution: string;
  /** False for CC0; kept explicit so the UI can say it is voluntary. */
  attributionRequired: boolean;
  publicPath: string;
  androidRaw: string;
  format: string;
  mime: string;
  durationSec: number;
  bytes: number;
  sampleRate: number;
  channels: number;
  bitrateKbps: number;
  sha256: string;
  bundled: boolean;
  redistributionAuthorized: boolean;
}

export interface AudioLicense {
  /** Still `"unknown"`: no licence accompanies the supplied files. */
  license: string;
  redistributionAuthorized: boolean;
  /** Artist tag found in the source metadata, if any. */
  tagArtist: string;
  note: string;
  source: string;
}

interface CatalogShape {
  generatedAt: string;
  license: string;
  redistributionAuthorized: boolean;
  tagArtist: string;
  licenseNote: string;
  source: string;
  bundleInApp?: boolean;
  localCopyDir?: string;
  tracks: Array<{
    number: number;
    id: string;
    name: string;
    publicPath: string;
    androidRaw: string;
    sourceName: string;
    localCopy?: string;
    bundled?: boolean;
    processed: {
      durationSec: number;
      bytes: number;
      sampleRate: number;
      channels: number;
      bitrateKbps: number;
      sha256: string;
    };
  }>;
}

const catalog = catalogJson as unknown as CatalogShape;

export const AUDIO_CATALOG_GENERATED_AT = catalog.generatedAt;
export const AUDIO_LOCAL_COPY_DIR = catalog.localCopyDir ?? 'audio-cleaned/';

/** True only when a written authorisation has been recorded in the catalogue. */
export const AUDIO_REDISTRIBUTION_OK = catalog.redistributionAuthorized === true;

export const ADHAN_TRACKS: readonly AdhanTrack[] = catalog.tracks.map((track) => ({
  number: track.number,
  id: track.id,
  name: track.name,
  publicPath: track.publicPath,
  androidRaw: track.androidRaw,
  sourceName: track.sourceName,
  localCopy: track.localCopy ?? `${AUDIO_LOCAL_COPY_DIR}azan-${track.number}.mp3`,
  // A track can only be bundled when the catalogue both marks it bundled *and*
  // records a written authorisation. One flag alone is not enough.
  bundled: track.bundled === true && catalog.redistributionAuthorized === true,
  durationSec: track.processed.durationSec,
  bytes: track.processed.bytes,
  sampleRate: track.processed.sampleRate,
  channels: track.processed.channels,
  bitrateKbps: track.processed.bitrateKbps,
  sha256: track.processed.sha256,
}));

/** Tracks that may actually be listed as playable built-ins. */
export const BUNDLED_ADHAN_TRACKS: readonly BundledAdhanTrack[] = [
  cc0Json as unknown as BundledAdhanTrack,
];

/** The bundled recording, exported for the attribution block and tests. */
export const CC0_ADHAN_TRACK = BUNDLED_ADHAN_TRACKS[0]!;

/** Default sound for a new installation: a real Adhan, not a test chime. */
export const DEFAULT_SOUND_ID = CC0_ADHAN_TRACK.id;

export const AUDIO_LICENSE: AudioLicense = {
  license: catalog.license,
  redistributionAuthorized: catalog.redistributionAuthorized,
  tagArtist: catalog.tagArtist,
  note: catalog.licenseNote,
  source: catalog.source,
};
